  CONSTRAINT `exam_mainexamprogress_user_id_9bfdf7d4_fk_web_user_id` FOREIGN KEY (`user_id`) REFERENCES `web_user` (`id`),
  CONSTRAINT `exam_mainexamprogress_chk_1` CHECK ((`total_questions` >= 0)),
  CONSTRAINT `exam_mainexamprogress_chk_2` CHECK ((`correct_answers` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=95 DEFAULT CHARSET=latin1;
